changeSet.sql:
GRANT EXECUTE ON FUNCTION nexus.cross_preview_384(text, text[])  TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.cross_preview_768(text, text[])  TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.cross_preview_1024(text, text[]) TO nexus_svc;

rollback.sql:
DO $$
BEGIN
    IF to_regprocedure('nexus.cross_preview_1024(text, text[])') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.cross_preview_1024(text, text[]) FROM nexus_svc;
    END IF;
    IF to_regprocedure('nexus.cross_preview_768(text, text[])') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.cross_preview_768(text, text[]) FROM nexus_svc;
    END IF;
    IF to_regprocedure('nexus.cross_preview_384(text, text[])') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.cross_preview_384(text, text[]) FROM nexus_svc;
    END IF;
END
$$;
